# =============================================================================
# X.509 certificate-chain verification tests
# =============================================================================

import std/strutils
import std/unittest

import se050_nim/errors
import se050_nim/x509_verify

const
  RootCertificateHex = ""
  IntermediateCertificateHex = ""
  LeafCertificateHex = ""
  WrongRootCertificateHex = ""

proc hexBytes(text: string): seq[uint8] =
  let compact = text.strip()
  doAssert (compact.len mod 2) == 0

  result = newSeq[uint8](compact.len div 2)
  for index in 0 ..< result.len:
    result[index] = uint8(parseHexInt(compact[index * 2 .. index * 2 + 1]))

suite "X.509 chain verification":
  let root = hexBytes(RootCertificateHex)
  let intermediate = hexBytes(IntermediateCertificateHex)
  let leaf = hexBytes(LeafCertificateHex)
  let wrongRoot = hexBytes(WrongRootCertificateHex)

  test "parses concatenated DER certificate bundles":
    var bundle = root
    bundle.add(intermediate)

    let parsed = parseDerCertificateBundle(bundle)
    check parsed.ok
    check parsed.value.len == 2
    check parsed.value[0] == root
    check parsed.value[1] == intermediate

  test "rejects empty DER certificate bundles":
    let parsed = parseDerCertificateBundle(newSeq[uint8]())
    check not parsed.ok
    check parsed.error.kind == seInvalidArgument

  test "rejects malformed DER certificate bundles":
    let parsed = parseDerCertificateBundle(@[0x30'u8, 0x82'u8, 0x01'u8])
    check not parsed.ok
    check parsed.error.kind == seInvalidResponse

  test "validates a leaf through an intermediate to the trusted root":
    let verified = verifyCertificateChain(
      leaf,
      @[root],
      @[intermediate]
    )

    check verified.ok
    check verified.value.trustAnchorCount == 1
    check verified.value.intermediateCount == 1

  test "rejects a chain when the intermediate is missing":
    let verified = verifyCertificateChain(leaf, @[root])

    check not verified.ok
    check verified.error.kind == seCertificateUntrusted

  test "rejects a chain rooted in an untrusted CA":
    let verified = verifyCertificateChain(
      leaf,
      @[wrongRoot],
      @[intermediate]
    )

    check not verified.ok
    check verified.error.kind == seCertificateUntrusted

  test "requires at least one trust anchor":
    let noAnchors: seq[seq[uint8]] = @[]
    let verified = verifyCertificateChain(
      leaf,
      noAnchors,
      @[intermediate]
    )

    check not verified.ok
    check verified.error.kind == seInvalidArgument
